              padding: 10px 20px;
              margin: 10px 5px;
              background-color: #3498db;
              color: white;
              border: none;
              border-radius: 4px;
              cursor: pointer;
              font-size: 14px;
            }
            button:hover {
              background-color: #2980b9;
            }
            .content {
              margin-top: 20px;
              padding: 20px;
              background-color: #ecf0f1;
              border-radius: 4px;
              min-height: 100px;
            }
          </style>
        </head>
        <body>
          <h1>Async Page Transitions</h1>
          <div>
            <button id="load-page-1">Load Page 1</button>
            <button id="load-page-2">Load Page 2</button>
            <button id="load-page-3">Load Page 3</button>
          </div>
          <div class="loading-spinner" id="spinner"></div>
