            const contentDiv = document.getElementById('content');
            const spinner = document.getElementById('spinner');

            async function loadPage(pageNumber) {
              // Fade out current content
              contentDiv.classList.remove('fade-in');
              contentDiv.classList.add('fade-out');

              // Show spinner
              spinner.classList.add('active');

              // Simulate async data loading
              await new Promise(resolve => setTimeout(resolve, 800));

              // Update content
              contentDiv.innerHTML = '<div class="content"><h2>Page ' + pageNumber + '</h2><p>This is page ' + pageNumber + ' content loaded asynchronously.</p><p id="page-' + pageNumber + '-marker">Page ' + pageNumber + ' is now visible</p></div>';

              // Hide spinner
              spinner.classList.remove('active');

              // Fade in new content
              contentDiv.classList.remove('fade-out');
              contentDiv.classList.add('fade-in');
            }

            document.getElementById('load-page-1').addEventListener('click', () => loadPage(1));
            document.getElementById('load-page-2').addEventListener('click', () => loadPage(2));
            document.getElementById('load-page-3').addEventListener('click', () => loadPage(3));
          </script>
        </body>
      </html>
    `);
  });

  test('should display loading spinner during async page transition', async ({ page }) => {
